import { Component, OnInit, OnDestroy, NgZone } from '@angular/core';
import { Router } from '@angular/router';
import { CapacitorNfc, NfcEvent } from '@capgo/capacitor-nfc';
import type { PluginListenerHandle } from '@capacitor/core';
import { NdefUtil } from '../../core/services/ndef.util';

const ANDROID_READER_FLAGS_WITH_NDEF = 0x1 | 0x2 | 0x4 | 0x8 | 0x100;

@Component({
  selector: 'app-responsable-nfc',
  templateUrl: './responsable-nfc.page.html'
})
export class ResponsableNfcPage implements OnInit, OnDestroy {
  codeClient = '';
  codeResponsable = '';
  nfcSupported = false;
  status: 'idle' | 'scanning' | 'writing' | 'success' | 'error' = 'idle';
  errorMsg = '';
  private nfcListener: PluginListenerHandle | null = null;

  constructor(private router: Router, private ngZone: NgZone) {}

  ngOnInit(): void {
    this.checkNfcSupport();
  }

  ngOnDestroy(): void {
    this.removeListener();
  }

  private async checkNfcSupport(): Promise<void> {
    try {
      const result = await CapacitorNfc.isSupported();
      this.nfcSupported = result.supported;
    } catch {
      this.nfcSupported = false;
    }
  }

  onCodeClientInput(event: any): void {
    this.codeClient = String(event.target.value ?? '').replace(/\s/g, '').replace(/[^0-9]/g, '');
    if (this.codeClient) {
      this.codeResponsable = this.codeClient + 'RE';
    } else {
      this.codeResponsable = '';
    }
  }

  generateCode(): void {
    const cleaned = this.codeClient.replace(/\s/g, '').replace(/[^0-9]/g, '');
    if (!cleaned) {
      this.status = 'error';
      this.errorMsg = 'Le code client est obligatoire.';
      return;
    }
    this.codeClient = cleaned;
    this.codeResponsable = cleaned + 'RE';
    this.status = 'idle';
    this.errorMsg = '';
  }

  async startWrite(): Promise<void> {
    if (!this.codeResponsable) {
      this.status = 'error';
      this.errorMsg = 'Le code client est obligatoire.';
      return;
    }

    if (!this.nfcSupported) {
      this.status = 'error';
      this.errorMsg = 'NFC non disponible sur cet appareil.';
      return;
    }

    this.status = 'scanning';

    try {
      await this.removeListener();
      this.nfcListener = await CapacitorNfc.addListener('nfcEvent', (event: NfcEvent) => {
        this.ngZone.run(() => this.handleTagDetected(event));
      });

      await CapacitorNfc.startScanning({
        alertMessage: 'Approchez la carte NFC',
        invalidateAfterFirstRead: false,
        androidReaderModeFlags: ANDROID_READER_FLAGS_WITH_NDEF
      });
    } catch (err: any) {
      console.error('Error starting scan:', err);
      this.status = 'error';
      this.errorMsg = err?.message ?? 'Erreur lors du démarrage du scan NFC.';
      this.removeListener();
    }
  }

  private async handleTagDetected(event: NfcEvent): Promise<void> {
    try {
      const records = NdefUtil.createTextRecords([this.codeResponsable], 'en');

      this.status = 'writing';
      await CapacitorNfc.write({
        records,
        allowFormat: true,
      });
      await this.cleanupAfterWrite();

      this.status = 'success';
    } catch (err: any) {
      this.status = 'error';
      const msg = err?.message ?? "Erreur lors de l'écriture NFC.";
      if (msg.includes('MifareClassic authentication failed')) {
        this.errorMsg = "Cette carte MIFARE Classic utilise des clés personnalisées ou est verrouillée. Utilisez des cartes vierges MIFARE Ultralight / NTAG (formatables NDEF) ou des cartes MIFARE Classic avec clés par défaut.";
      } else if (msg.includes('Tag became stale')) {
        this.errorMsg = "La carte a été retirée trop vite. Approchez-la à nouveau et réessayez.";
      } else {
        this.errorMsg = msg;
      }
      this.cleanupAfterWrite();
    }
  }

  private async cleanupAfterWrite(): Promise<void> {
    try {
      await CapacitorNfc.stopScanning();
    } catch (stopErr) {
      console.warn('Error stopping scan:', stopErr);
    }
    try {
      await this.removeListener();
    } catch (listenerErr) {
      console.warn('Error removing listener:', listenerErr);
    }
  }

  reset(): void {
    this.status = 'idle';
    this.errorMsg = '';
  }

  goBack(): void {
    this.removeListener();
    this.router.navigate(['/parametres']);
  }

  private async removeListener(): Promise<void> {
    if (this.nfcListener) {
      await this.nfcListener.remove();
      this.nfcListener = null;
    }
  }
}
<div class="pg">

  <!-- Back -->
  <div class="detail-back">
    <button class="btn btn-ghost btn-sm" (click)="goBack()">
      <ion-icon name="arrow-back-outline"></ion-icon> Retour
    </button>
  </div>

  <!-- Header -->
  <div class="pg-header">
    <div>
      <h1 class="pg-title">Création Carte NFC Responsable</h1>
      <p class="pg-sub">Saisissez un code client pour générer et écrire le code responsable sur une carte NFC.</p>
    </div>
  </div>

  <!-- Form Card -->
  <div class="card" style="max-width: 640px;">
    <div class="card-header">
      <span class="card-title">Informations carte</span>
    </div>
    <div class="card-body">

      <!-- Code Client -->
      <div class="form-group">
        <label class="form-label">Code Client <span class="required">*</span></label>
        <input
          class="form-input"
          type="text"
          placeholder="ex: 0001006155"
          [value]="codeClient"
          (input)="onCodeClientInput($event)"
          inputmode="numeric"
          autocomplete="off"
        >
        <div class="form-hint">Chiffres uniquement, sans espaces.</div>
      </div>

      <!-- Code Responsable -->
      <div class="form-group mt-4">
        <label class="form-label">Code Responsable</label>
        <input
          class="form-input"
          type="text"
          [value]="codeResponsable"
          disabled
          readonly
          style="background:var(--c-surface); color:var(--c-muted); cursor:not-allowed;"
        >
        <div class="form-hint">Généré automatiquement à partir du code client (suffixe « RE »).</div>
      </div>

      <!-- Actions -->
      <div class="action-stack mt-4">
   <!--      <button class="btn btn -outline" (click)="generateCode()">
          <ion-icon name="create-outline"></ion-icon> Générer le code Responsable
        </button> -->
        <button class="btn btn-primary" (click)="startWrite()">
          <ion-icon name="card-outline"></ion-icon> Écrire sur la carte NFC
        </button>
      </div>

    </div>
  </div>

  <!-- Messages -->
  <div *ngIf="status === 'success'" class="card mt-4" style="max-width: 640px; border-color: var(--c-success);">
    <div class="card-body" style="display:flex; align-items:center; gap:12px;">
      <span style="font-size:22px;">✅</span>
      <div>
        <div style="font-weight:600; color:var(--c-success);">Carte Responsable créée avec succès.</div>
        <div class="form-hint">Le code <strong>{{ codeResponsable }}</strong> a été écrit sur la carte NFC.</div>
      </div>
      <button class="btn btn-ghost btn-sm" style="margin-left:auto;" (click)="reset()">Écrire une autre carte</button>
    </div>
  </div>

  <div *ngIf="status === 'error'" class="card mt-4" style="max-width: 640px; border-color: var(--c-danger);">
    <div class="card-body" style="display:flex; align-items:center; gap:12px;">
      <span style="font-size:22px;">❌</span>
      <div>
        <div style="font-weight:600; color:var(--c-danger);">Impossible d'écrire sur la carte NFC.</div>
        <div class="form-error">{{ errorMsg }}</div>
      </div>
      <button class="btn btn-ghost btn-sm" style="margin-left:auto;" (click)="reset()">Réessayer</button>
    </div>
  </div>

  <!-- Waiting state -->
  <div *ngIf="status === 'scanning'" class="card mt-4" style="max-width: 640px;">
    <div class="nfc-state-body">
      <div class="nfc-spinner"></div>
      <div class="nfc-state-title" style="color:var(--c-sky);">En attente de la carte...</div>
      <div class="nfc-state-desc">Approchez la carte NFC de votre appareil</div>
      <button class="btn btn-ghost btn-sm" (click)="reset()">Annuler</button>
    </div>
  </div>

  <div *ngIf="status === 'writing'" class="card mt-4" style="max-width: 640px;">
    <div class="nfc-state-body">
      <div class="nfc-spinner"></div>
      <div class="nfc-state-title" style="color:var(--c-sky);">Écriture en cours...</div>
      <div class="nfc-state-desc">Maintenez la carte NFC près de l'appareil</div>
    </div>
  </div>

  <!-- NFC not supported -->
  <div *ngIf="!nfcSupported" class="card mt-4" style="max-width: 640px;">
    <div class="card-body">
      <div class="warning-banner">
        <ion-icon name="warning-outline"></ion-icon>
        <div>
          <div style="font-weight:600; color:#d97706;">NFC non disponible</div>
          <div style="font-size:12px; color:var(--c-muted); margin-top:3px;">
            Cet appareil ne supporte pas le NFC ou l'accès n'est pas autorisé.
          </div>
        </div>
      </div>
    </div>
  </div>

</div>
